const e=["Dieu","Folie","Religion","Force","Mystère"],t="Tumtum était là.",n="Dieu de la Folie",r=["Tumtum représente la Folie.","Il incarne ce qui échappe à la logique, à la raison et aux certitudes.","La folie n'est pas nécessairement l'absence de pensée.","Un individu peut être capable de raisonner tout en poursuivant une idée que personne d'autre ne comprend.","Pour cette raison, le domaine de Tumtum touche autant aux hallucinations et aux comportements irrationnels qu'aux obsessions, aux visions et aux vérités que personne ne veut entendre."],s=[{label:"Domaines",value:"Folie"},{label:"Symboles",value:"Un masque souriant, un œil déformé, une cloche, un miroir brisé, un sourire, une spirale"}],i=[{title:"La frontière",title_border:"#e8553d",type:"text",content:["Les traditions de Tumtum accordent une grande importance à la frontière entre raison et folie.","Cette frontière n'est pas toujours aussi nette que les mortels le prétendent.","Une vision peut être une hallucination.","Elle peut aussi être un avertissement.","Une idée absurde peut être réellement absurde.","Elle peut également être une découverte que personne n'était encore capable de comprendre.","Les fidèles de Tumtum ne cherchent donc pas systématiquement à déterminer ce qui est fou.","Ils cherchent à comprendre pourquoi quelqu'un le croit."]},{title:"Le rire",title_border:"#c2660a",type:"text",content:["Le rire est souvent associé à Tumtum.","Il peut représenter la joie, mais également le malaise, la peur ou l'incompréhension.","Dans certaines traditions, rire face à une situation terrifiante est considéré comme une manière de rappeler que la réalité ne se comporte pas toujours comme les mortels l'attendent."]},{title:"Le culte de Tumtum",title_border:"#6f9fd8",type:"text",content:["Le culte de Tumtum est rarement organisé.","Ses fidèles peuvent être des ermites, des artistes, des prophètes autoproclamés, des marginaux ou simplement des personnes fascinées par ce que les autres refusent de regarder.","Il existe peu de véritables temples.","On raconte cependant que certains sanctuaires de Tumtum sont volontairement construits selon des plans impossibles à comprendre : couloirs qui ne semblent mener nulle part, pièces asymétriques ou portes qui ne s'ouvrent jamais de la même manière.","Personne ne sait combien de ces histoires sont vraies."]},{title:"Tumtum et Eone",title_border:"#e8553d",type:"text",content:["La relation entre Tumtum et Eone est souvent étudiée par les érudits.","La Connaissance cherche à comprendre.","La Folie rappelle que comprendre n'est pas toujours possible.","Certains chercheurs pensent que toute découverte importante commence par une idée qui semble absurde.","D'autres considèrent au contraire que cette philosophie permet surtout de justifier n'importe quelle croyance.","Aucune réponse ne fait consensus."]},{title:"Tumtum et Phiella",title_border:"#c2660a",type:"text",content:["La Tentation et la Folie peuvent également se rejoindre.","Une obsession peut commencer par un désir.","Puis devenir une conviction.","Puis devenir une nécessité.","À quel moment le désir cesse-t-il d'être un choix ?","Les théologiens de Tumtum débattent encore de cette question."]},{title:"Symboles",title_border:"#6f9fd8",type:"text",content:"Tumtum est souvent représenté par :"},{title:"",type:"list",content:["Un masque souriant","Un œil déformé","Une cloche","Un miroir brisé","Un sourire","Une spirale"]},{title:"",type:"text",content:["Le miroir brisé est particulièrement répandu.","Chaque fragment reflète une partie du monde, mais aucun ne permet de voir l'ensemble."]},{title:"Aujourd'hui",title_border:"#e8553d",type:"text",content:["Tumtum est rarement prié volontairement.","Son nom est plutôt invoqué lorsqu'un événement défie toute explication.","Certains disent :","Cela peut être une plaisanterie.","Une superstition.","Ou parfois une manière de reconnaître que personne ne comprend réellement ce qui vient de se produire."]}],o=["Les Dieux","Les Forces de la Conscience","Eone","Phiella","La Folie"],u={tags:e,citation:t,surname:n,presentation:r,infos:s,sections:i,related:o};export{t as citation,u as default,s as infos,r as presentation,o as related,i as sections,n as surname,e as tags};
